-- ApplyUni core schema (SQLite). Same tables as migrations/postgres.
-- IDs are UUID strings generated by the application. Emails are stored lowercased.
-- SQLite has no row-level security: every tenant query filters by org_id in code.

CREATE TABLE organizations (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  kind        TEXT NOT NULL CHECK (kind IN ('personal', 'agency', 'school')),
  plan        TEXT NOT NULL DEFAULT 'free',
  seat_limit  INTEGER NOT NULL DEFAULT 1,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE users (
  id             TEXT PRIMARY KEY,
  username       TEXT NOT NULL UNIQUE,  -- stored lowercased
  email          TEXT UNIQUE,           -- optional, stored lowercased
  password_hash  TEXT NOT NULL,
  full_name      TEXT NOT NULL,
  created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE memberships (
  user_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  org_id   TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  role     TEXT NOT NULL CHECK (role IN ('owner', 'counselor', 'student', 'parent')),
  PRIMARY KEY (user_id, org_id)
);

-- ---------- Catalogue (public) ----------

CREATE TABLE countries (
  code        TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  rules       TEXT NOT NULL,          -- JSON, see internal/requirements
  source_url  TEXT,
  verified_at DATE
);

CREATE TABLE universities (
  id            TEXT PRIMARY KEY,
  country_code  TEXT NOT NULL REFERENCES countries(code),
  name          TEXT NOT NULL,
  city          TEXT,
  portal        TEXT NOT NULL,
  website       TEXT,
  UNIQUE (country_code, name)
);

CREATE TABLE programs (
  id                  TEXT PRIMARY KEY,
  university_id       TEXT NOT NULL REFERENCES universities(id) ON DELETE CASCADE,
  name                TEXT NOT NULL,
  degree              TEXT NOT NULL CHECK (degree IN ('bachelor', 'master')),
  language            TEXT NOT NULL DEFAULT 'en',
  tuition_eur_year    INTEGER,
  application_fee_eur INTEGER,
  deadline            DATE,           -- NULL = not verified yet; never guess
  intake              TEXT,
  requirements        TEXT NOT NULL DEFAULT '{}',
  source_url          TEXT,
  verified_at         DATE,
  UNIQUE (university_id, name, degree)
);

-- ---------- Tenant data ----------

CREATE TABLE students (
  id           TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  user_id      TEXT REFERENCES users(id) ON DELETE SET NULL,
  full_name    TEXT NOT NULL,
  email        TEXT,
  email_alias  TEXT,
  profile      TEXT NOT NULL DEFAULT '{}',
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX students_org ON students (org_id);

CREATE TABLE applications (
  id            TEXT PRIMARY KEY,
  org_id        TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  student_id    TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  program_id    TEXT NOT NULL REFERENCES programs(id),
  status        TEXT NOT NULL DEFAULT 'collecting_documents' CHECK (status IN (
                  'collecting_documents', 'ready_for_review', 'approved',
                  'submitting', 'submitted', 'needs_attention', 'withdrawn')),
  status_note   TEXT,
  portal_ref    TEXT,
  submitted_at  TIMESTAMP,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (student_id, program_id)
);
CREATE INDEX applications_org ON applications (org_id);

-- Envelope-encrypted files: ciphertext lives in the object store, only the
-- wrapped (encrypted) data key is stored here.
CREATE TABLE documents (
  id            TEXT PRIMARY KEY,
  org_id        TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  student_id    TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  doc_type      TEXT NOT NULL,
  filename      TEXT NOT NULL,
  content_type  TEXT NOT NULL,
  size_bytes    INTEGER NOT NULL,
  sha256        BLOB NOT NULL,
  object_key    TEXT NOT NULL,
  nonce         BLOB NOT NULL,
  wrapped_dek   BLOB NOT NULL,
  key_ref       TEXT NOT NULL,
  status        TEXT NOT NULL DEFAULT 'uploaded' CHECK (status IN ('uploaded', 'analyzing', 'accepted', 'rejected')),
  ai_result     TEXT,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX documents_student ON documents (student_id);

CREATE TABLE approvals (
  id               TEXT PRIMARY KEY,
  org_id           TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  application_id   TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,
  user_id          TEXT NOT NULL REFERENCES users(id),
  snapshot_sha256  BLOB NOT NULL,
  snapshot         TEXT NOT NULL,
  ip               TEXT,
  user_agent       TEXT,
  approved_at      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE portal_accounts (
  id           TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  student_id   TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  portal       TEXT NOT NULL,
  username     TEXT NOT NULL,
  secret_ct    BLOB NOT NULL,
  nonce        BLOB NOT NULL,
  wrapped_dek  BLOB NOT NULL,
  key_ref      TEXT NOT NULL,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (student_id, portal)
);

CREATE TABLE jobs (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  org_id      TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL,
  payload     TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed')),
  attempts    INTEGER NOT NULL DEFAULT 0,
  run_after   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_error  TEXT,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX jobs_ready ON jobs (status, run_after);

CREATE TABLE audit_log (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  org_id     TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  user_id    TEXT,
  action     TEXT NOT NULL,
  target     TEXT,
  at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
